function mountFpsTuner(){
 if(!document.body||!document.head){document.addEventListener("DOMContentLoaded",mountFpsTuner,{once:true});return;}
 if(document.getElementById("fpsTunerPanel"))return;
 const style=document.createElement("style");
 style.id="fpsTunerStyle";
 style.textContent=`#fpsTunerPanel{position:fixed;z-index:2147483000;right:8px;top:8px;width:min(380px,calc(100vw - 16px));max-height:88vh;overflow:auto;overscroll-behavior:contain;box-sizing:border-box;padding:12px;background:rgba(8,15,26,.97);color:#f3f7fc;border:1px solid #526d89;border-radius:12px;box-shadow:0 8px 30px #000a;font:13px/1.4 system-ui,sans-serif;touch-action:pan-y;transform-origin:top right}#fpsTunerPanel *{box-sizing:border-box}#fpsTunerPanel .ft-head{position:sticky;top:-12px;z-index:2;display:flex;align-items:center;justify-content:space-between;gap:8px;margin:-12px -12px 8px;padding:12px;background:#101f31;border-bottom:1px solid #49617b;font-size:16px;font-weight:800}#fpsTunerPanel .ft-group{margin:12px 0 6px;padding:8px 3px 5px;border-top:1px solid #3c5268;color:#8fc9ff;font-weight:800;letter-spacing:.05em}#fpsTunerPanel .ft-row{display:grid;grid-template-columns:minmax(0,1fr) 90px;gap:5px 8px;align-items:center;margin:8px 0;padding:4px 2px;border-bottom:1px solid #1d2c3d}#fpsTunerPanel .ft-row label{font-weight:600;overflow-wrap:anywhere}#fpsTunerPanel .ft-row output{text-align:right;font-variant-numeric:tabular-nums;color:#ffd778;font-weight:800}#fpsTunerPanel input[type=range]{grid-column:1/3;width:100%;height:25px;margin:0;accent-color:#35b7ff;touch-action:pan-x}#fpsTunerPanel button,#fpsTunerToggle{border:1px solid #6d8ba8;border-radius:8px;background:#18334d;color:white;padding:8px 10px;font-weight:700}#fpsTunerPanel .ft-actions{display:flex;gap:7px;flex-wrap:wrap;margin:10px 0}#fpsTunerPanel .ft-actions button{flex:1}#fpsTunerPanel .ft-note{margin:8px 0;color:#bac8d6;font-size:11px}#fpsTunerToggle{position:fixed;z-index:2147483001;right:10px;top:10px;padding:10px 14px;background:#075b91;box-shadow:0 3px 14px #0008;display:none}`;
 document.head.appendChild(style);
 const panel=document.createElement("div");panel.id="fpsTunerPanel";
 const head=document.createElement("div");head.className="ft-head";
 const title=document.createElement("span");title.textContent="FPS 65項目 強化パネル";
 const close=document.createElement("button");close.type="button";close.textContent="閉じる";close.id="fpsTunerClose";
 head.append(title,close);panel.appendChild(head);
 const controls=new Map();
 let group="";
 for(const f of FPS_TUNER_FIELDS){
  const [g,k,label,min,max,step,def,unit]=f;
  if(group!==g){group=g;const h=document.createElement("div");h.className="ft-group";h.textContent=g;panel.appendChild(h);}
  const row=document.createElement("div");row.className="ft-row";
  const lab=document.createElement("label");lab.htmlFor="ft-"+k;lab.textContent=label;
  const out=document.createElement("output");out.id="ft-"+k+"-v";
  const input=document.createElement("input");input.type="range";input.id="ft-"+k;input.min=min;input.max=max;input.step=step;input.dataset.key=k;input.value=fpsTuner[k];
  row.append(lab,out,input);panel.appendChild(row);controls.set(k,{input,out,unit});
 }
 const actions=document.createElement("div");actions.className="ft-actions";
 const maxBtn=document.createElement("button");maxBtn.type="button";maxBtn.textContent="プレイヤー最大強化";
 const weakBtn=document.createElement("button");weakBtn.type="button";weakBtn.textContent="CPUを弱体化";
 const resetBtn=document.createElement("button");resetBtn.type="button";resetBtn.textContent="標準に戻す";
 actions.append(maxBtn,weakBtn,resetBtn);panel.appendChild(actions);
 const note=document.createElement("div");note.className="ft-note";note.textContent="設定はこの端末のブラウザーに自動保存されます。CPU人数・試合時間は次の試合から反映。オンライン対戦では相手側に同じ設定は適用されません。ボール上限や発射数を増やすと処理負荷が上がります。";panel.appendChild(note);
 const toggle=document.createElement("button");toggle.id="fpsTunerToggle";toggle.type="button";toggle.textContent="FPS強化";
 document.body.append(panel,toggle);
 function fmt(v){return Number(v).toFixed(Number(v)%1?2:0).replace(/0+$/,'').replace(/\.$/,'')}
 function sync(){for(const [k,c] of controls){c.input.value=fpsTuner[k];c.out.textContent=fmt(fpsTuner[k])+c.unit;}}
 function save(){try{localStorage.setItem(FPS_TUNER_KEY,JSON.stringify(fpsTuner));}catch(e){}}
 function setValue(key,value){
  const lim=FPS_TUNER_LIMITS[key];let v=Number(value);if(!lim||!Number.isFinite(v))return false;
  v=Math.min(lim[1],Math.max(lim[0],v));const old=fpsTuner[key],oldHp=key==="health"?playerMaxHp():0,oldPlayerHp=p_hp,oldPlayerHpView=p_hp_view;fpsTuner[key]=v;
  if(key==="health"){const nextHp=playerMaxHp(),hpRatio=oldHp>0?oldPlayerHp/oldHp:1,viewRatio=oldHp>0?oldPlayerHpView/oldHp:hpRatio;p_hp=nextHp*Math.max(0,Math.min(1,hpRatio));p_hp_view=nextHp*Math.max(0,Math.min(1,viewRatio));}
  if(key==="botHp"&&old>0){const ratio=v/old;for(const b of bots)if(!b.dying){b.hp=Math.min(100*v,b.hp*ratio);b.maxHp=100*v;}}
  if(key==="ballSize"){BALL_R=.84*BALL_SCALE*v;for(const b of balls)b.mesh.scale.setScalar(BALL_SCALE*v);}
  if(key==="brightness"&&renderer)renderer.toneMappingExposure=1.2*v;
  if(key==="soundVolume")vlm=1.6*v;
  if(key==="explosionSize"&&expMat)expMat.size=.14*v;
  if(key==="ballGlow"){for(const b of balls)b.mesh.traverse(m=>{if(m.isMesh&&m.material){const mats=Array.isArray(m.material)?m.material:[m.material];for(const mat of mats)if(mat.emissive){mat.emissive.setHex(v?0x39aaff:0x000000);mat.emissiveIntensity=v;}}});}
  if(key==="hudScale")panel.style.transform="scale("+v+")";
  save();sync();if(typeof requestDraw==="function")requestDraw();return true;
 }
 panel.addEventListener("input",e=>{const el=e.target;if(el&&el.dataset&&el.dataset.key)setValue(el.dataset.key,el.value);});
 function show(){panel.style.display="block";toggle.style.display="none";}
 function hide(){panel.style.display="none";toggle.style.display="block";}
 function reset(){for(const k of Object.keys(FPS_TUNER_DEFAULTS))setValue(k,FPS_TUNER_DEFAULTS[k]);prm1=prm2=prm3=0;saveStoredParams();save();sync();}
 close.addEventListener("click",hide);toggle.addEventListener("click",show);
 maxBtn.addEventListener("click",()=>{for(const [k,v] of Object.entries({health:10,move:5,reload:10,damage:10,damageTaken:0,regen:50,invulnSecs:5,spawnProtection:15,kickCost:0,pickupRecovery:3,turnSpeed:5,shotCount:5,ballPower:5,ballSize:2,maxBalls:120,ballLife:180,curvePower:5,straightPower:5,rollingPower:5,scoreMultiplier:10}))setValue(k,v);});
 weakBtn.addEventListener("click",()=>{for(const [k,v] of Object.entries({botSpeed:.25,botHp:.25,botAttackRate:.25,botAimTime:3,botAttackRange:8,botAccuracy:0,botReload:.25,botThinkSpeed:.25,botTurnSpeed:.25,botDamage:.1}))setValue(k,v);});
 resetBtn.addEventListener("click",reset);
 sync();panel.style.transform="scale("+fpsTuner.hudScale+")";
 window.__fpsTunerAPI=Object.freeze({version:65,getSettings:()=>({...fpsTuner}),set:setValue,setMany:values=>{if(values&&typeof values==="object")for(const [k,v] of Object.entries(values))setValue(k,v);},show,hide,toggle:()=>panel.style.display==="none"?show():hide(),reset});
}
mountFpsTuner();updateCamera(0),requestDraw();